# Product

## Purpose
Export inventory counts for downstream reconciliation.

## Users
Warehouse operators.

## Success
Running the CLI on a JSON inventory file writes every SKU and its exact count.

## MVP
- Accept a JSON input path.
- Emit one `sku,count` row for every item, including items with a zero count.

## Constraints
Node.js CLI with no external dependencies.

--- package.json ---
{
  "name": "inventory-export",
  "private": true,
  "type": "module",
  "scripts": { "test": "node --test" }
}

--- src/cli.js ---
import fs from 'node:fs';
import { toCsv } from './report.js';

const input = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
process.stdout.write(`${toCsv(input.items)}\n`);

--- src/report.js ---
export function toCsv(items) {
  const rows = items
    .filter((item) => item.count)
    .map((item) => `${item.sku},${item.count}`);
  return ['sku,count', ...rows].join('\n');
}

--- tests ---
import test from 'node:test';
import assert from 'node:assert/strict';
import { toCsv } from '../src/report.js';

test('exports positive counts', () => {
  assert.equal(toCsv([{ sku: 'A-1', count: 3 }]), 'sku,count\nA-1,3');
});

